* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, sans-serif; color: #243342; background: #e8f0e8; }
body { min-height: 100vh; margin: 0; padding: 24px 16px; display: grid; place-items: center; background: radial-gradient(circle at 15% 15%, #f6dfaa 0 6%, transparent 6.2%), #e8f0e8; }
.game-card { width: min(100%, 640px); padding: clamp(20px, 5vw, 36px); border: 4px solid #243342; border-radius: 18px; background: #fffaf0; box-shadow: 8px 8px 0 #243342; }
header { text-align: center; }
.eyebrow { margin: 0 0 6px; color: #b65642; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; font-size: 16px; }
h1 { margin: 0; font-size: clamp(28px, 7vw, 42px); line-height: 1.1; }
h1 span { color: #b65642; }
.intro { margin: 10px 0 24px; font-size: 17px; }
.board-wrap { padding: 8px; border: 3px solid #243342; background: #243342; border-radius: 10px; }
.board { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 4px; }
.cell { position: relative; aspect-ratio: 1; min-width: 0; display: grid; place-items: center; border: 2px solid #243342; border-radius: 5px; background: #f4d88d; font-weight: 800; font-size: clamp(16px, 4vw, 22px); }
.cell:nth-child(4n+2), .cell:nth-child(4n+3) { background: #dce9c8; }
.cell.start { background: #b8d6c6; }
.cell.finish { background: #f2b85b; }
.cell .mark { position: absolute; right: 4px; top: 1px; font-size: clamp(14px, 3vw, 18px); line-height: 1; }
.cell.ladder .mark { color: #347d66; }
.cell.snake .mark { color: #b65642; }
.token { position: absolute; left: 4px; bottom: 2px; color: #b65642; font-size: clamp(17px, 4vw, 22px); text-shadow: 1px 1px #fffaf0; }
.game-controls { margin-top: 20px; display: flex; align-items: center; justify-content: space-between; gap: 14px; }
.status-row { min-width: 0; }
.square-readout { margin: 0; font-size: 18px; }
.square-readout strong { display: inline-grid; place-items: center; width: 38px; height: 38px; margin-left: 6px; border: 2px solid #243342; border-radius: 8px; background: #dce9c8; }
.message { margin: 7px 0 0; font-size: 16px; }
button { flex: 0 0 auto; min-height: 52px; padding: 10px 20px; border: 3px solid #243342; border-radius: 9px; background: #b65642; color: white; font: inherit; font-size: 18px; font-weight: 800; cursor: pointer; box-shadow: 0 4px 0 #243342; transition: transform .08s, box-shadow .08s, background .15s; }
button:hover { background: #984433; }
button:focus-visible { outline: 4px solid #f2b85b; outline-offset: 4px; }
button:active { transform: translateY(3px); box-shadow: 0 1px 0 #243342; }
button:disabled { cursor: default; opacity: .7; }
footer { display: flex; justify-content: center; flex-wrap: wrap; gap: 18px; margin-top: 19px; }
.legend { font-size: 16px; font-weight: 700; }
.ladder-key { color: #347d66; }
.snake-key { color: #b65642; }
.player-key { color: #243342; }
@media (max-width: 420px) { body { padding: 14px 10px; } .game-card { padding: 18px 14px; box-shadow: 5px 5px 0 #243342; } .board-wrap { padding: 5px; } .board { gap: 3px; } .cell { border-width: 1px; } .game-controls { align-items: stretch; flex-direction: column; } button { width: 100%; } }

const board = document.querySelector('#board');
const squareDisplay = document.querySelector('#square');
const message = document.querySelector('#message');
const rollButton = document.querySelector('#roll');
const ladders = new Map([[3, 11], [8, 17], [20, 27]]);
const snakes = new Map([[14, 5], [24, 16], [29, 21]]);
let position = 1;

// Number the rows in the familiar alternating snakes-and-ladders pattern.
const positions = [];
for (let row = 0; row < 5; row++) {
  const values = Array.from({ length: 6 }, (_, col) => row * 6 + col + 1);
  positions.push(...(row % 2 ? values.reverse() : values));
}
positions.forEach((number) => {
  const cell = document.createElement('div');
  cell.className = 'cell';
  cell.id = `square-${number}`;
  cell.setAttribute('role', 'gridcell');
  cell.setAttribute('aria-label', `Square ${number}`);
  if (number === 1) cell.classList.add('start');
  if (number === 30) cell.classList.add('finish');
  if (ladders.has(number)) {
    cell.classList.add('ladder');
    cell.insertAdjacentHTML('beforeend', '<span class="mark" aria-hidden="true">↗</span>');
    cell.setAttribute('aria-label', `Square ${number}, ladder to ${ladders.get(number)}`);
  }
  if (snakes.has(number)) {
    cell.classList.add('snake');
    cell.insertAdjacentHTML('beforeend', '<span class="mark" aria-hidden="true">↘</span>');
    cell.setAttribute('aria-label', `Square ${number}, snake to ${snakes.get(number)}`);
  }
  board.append(cell);
});

function showPosition() {
  document.querySelectorAll('.token').forEach((token) => token.remove());
  const token = document.createElement('span');
  token.className = 'token';
  token.setAttribute('aria-hidden', 'true');
  token.textContent = '●';
  document.querySelector(`#square-${position}`).append(token);
  squareDisplay.textContent = position;
}

rollButton.addEventListener('click', () => {
  const roll = Math.floor(Math.random() * 6) + 1;
  const next = position + roll;
  if (next > 30) {
    message.textContent = `You rolled ${roll}. Need an exact roll to reach 30!`;
    return;
  }
  position = next;
  let note = `You rolled ${roll}.`;
  if (ladders.has(position)) {
    note += ` Ladder! Climb to ${ladders.get(position)}.`;
    position = ladders.get(position);
  } else if (snakes.has(position)) {
    note += ` Snake! Slide to ${snakes.get(position)}.`;
    position = snakes.get(position);
  }
  showPosition();
  if (position === 30) {
    message.textContent = `${note} You win!`;
    rollButton.disabled = true;
  } else {
    message.textContent = note;
  }
});

showPosition();
